import unreal,json
s=unreal.get_editor_subsystem(unreal.StaticMeshEditorSubsystem); e=unreal.get_editor_subsystem(unreal.EditorAssetSubsystem); rows=[]
with unreal.ScopedEditorTransaction('Rebuild mall balcony deck and rail collision'):
 for n in ['SM_MallBalconyStraight_400','SM_MallBalconyModule_400']:
  m=unreal.load_asset('/Game/Environment/Mall/Models/Architecture/'+n)
  if not m: raise RuntimeError('Missing '+n)
  m.modify()
  for i in range(m.get_num_sections(0)): s.enable_section_collision(m,True,0,i)
  saved=e.save_loaded_asset(m,False)
  if not saved: raise RuntimeError('Could not save '+n)
  rows.append({'mesh':n,'saved':saved,'collision':str(s.get_collision_complexity(m)),'sections':[s.is_section_collision_enabled(m,0,i) for i in range(m.get_num_sections(0))]})
unreal.log(json.dumps(rows))
